            subscribe=subscribe,
            target_path=target_path,
            stats=stats,
        ) or [])
        if not planned or subscribe is None or not self._is_movie_subscription(subscribe):
            return planned

        video_paths = [
            str(row.get("relative_path") or row.get("name") or "").strip()
            for row in (probe.get("files") or [])
            if isinstance(row, dict)
            and _is_video(str(row.get("relative_path") or row.get("name") or ""))
        ]
        if not video_paths:
            return []
        roots_fn = getattr(self, "_direct_share_primary_roots_v11214", None)
        primary: List[str] = []
        if callable(roots_fn):
            try:
                primary = list(roots_fn(video_paths, getattr(subscribe, "year", None)) or [])
            except Exception:
                primary = []
        assessment = self._movie_actual_gate_v11219(
            subscribe,
            primary=primary,
            files=video_paths,
            origin="guangya_share",
        )
        if not bool(assessment.get("ok")):
            if stats is not None:
                stats["movie_actual_reject_v11219"] = 1
            return []
        return planned

    def _resolve_offline_source(self, source: Dict[str, Any], subscribe: Any) -> Dict[str, Any]:
        result = dict(super()._resolve_offline_source(source, subscribe) or {})
        source_id = str(source.get("id") or "")
        resolve_data = result.get("resolve_data") if isinstance(result.get("resolve_data"), dict) else {}
        bt_info = resolve_data.get("btResInfo") if isinstance(resolve_data.get("btResInfo"), dict) else {}
        subfiles = bt_info.get("subfiles") if isinstance(bt_info.get("subfiles"), list) else []

        if self._is_movie_subscription(subscribe):
            video_files = []
            for row in subfiles:
                if not isinstance(row, dict):
                    continue
                name = str(row.get("fileName") or row.get("name") or "").strip()
                if name and _is_video(name):
                    video_files.append(name)
            resolved_name = str(result.get("resolved_name") or bt_info.get("fileName") or "").strip()
            if not video_files and resolved_name and _is_video(resolved_name):
                video_files.append(resolved_name)
            if not video_files:
                raise RuntimeError("EPISODE_AMBIGUOUS:电影真实 payload 未发现可验证的视频文件")

            assessment = self._movie_actual_gate_v11219(
                subscribe,
                primary=[resolved_name, str(bt_info.get("fileName") or "").strip()],
                files=video_files,
                origin=str(source.get("type") or "offline"),
            )
            if not bool(assessment.get("ok")):
                raise RuntimeError(
                    "EPISODE_AMBIGUOUS:电影真实资源身份拒绝："
                    + str(assessment.get("reason") or "置信度不足")[:320]
                )
            if source_id:
                self._update_source(
                    source_id,
                    media_match_verified_v11219=True,
                    media_match_score_v11219=int(assessment.get("score") or 0),
                    media_match_reason_v11219=str(assessment.get("reason") or "")[:320],
                    requested_episodes=[],
                    candidate_episodes=[],
                    resolved_episodes=[],
                    transfer_episodes=[],
                )
            result["media_match_verified_v11219"] = True
            result["media_match_score_v11219"] = int(assessment.get("score") or 0)
            return result

        physical = _positive_episode_set_v11219(result.get("physical_episodes_v11214") or [])
        latest: Dict[str, Any] = {}
        if source_id:
            try:
                latest = dict((self._source_store().get("items") or {}).get(source_id) or {})
            except Exception:
                latest = {}
        if not physical:
            physical = _positive_episode_set_v11219(latest.get("resolved_episodes") or [])
        if not physical:
            raise RuntimeError("EPISODE_AMBIGUOUS:真实资源已解析，但无法确认任何可转存剧集")

        allowed_fn = getattr(self, "_authoritative_missing_v11214", None)
        if callable(allowed_fn):
            allowed = set(allowed_fn(subscribe, current_source_id=source_id) or set())
            if not physical.issubset(allowed):
                raise RuntimeError(
                    "EPISODE_AMBIGUOUS:最终物理集超出 MoviePilot 当前真实缺集："
                    f"physical={sorted(physical)} allowed={sorted(allowed)}"
                )

        requested = _positive_episode_set_v11219(
            latest.get("requested_episodes")
            or source.get("requested_episodes")
            or source.get("target_episodes")
            or []
        )
        candidate = _positive_episode_set_v11219(
            latest.get("candidate_episodes") or source.get("candidate_episodes") or []
        )
        if source_id:
            self._update_source(
                source_id,
                media_match_verified_v11219=True,
                media_match_score_v11219=int(result.get("identity_score_v1111") or 0),
                media_match_reason_v11219=str(result.get("identity_reason_v1111") or "真实媒体身份与物理集均已通过")[:320],
                requested_episodes=sorted(requested),
                candidate_episodes=sorted(candidate),
                resolved_episodes=sorted(physical),
                transfer_episodes=sorted(physical),
            )
        result["transfer_episodes_v11219"] = sorted(physical)
        result["media_match_verified_v11219"] = True
        return result

    def _xunlei_json_identity_matches_v1123(
        self,
        subscribe: Any,
        candidate: Dict[str, Any],
        info: Dict[str, Any],
        template: Dict[str, Any],
    ) -> tuple[bool, str]:
        """迅雷电影最终执行前按真实分享标题与视频路径再次验真。"""
        accepted, reason = super()._xunlei_json_identity_matches_v1123(
            subscribe,
            candidate,
            info,
            template,
        )
        if not accepted or not self._is_movie_subscription(subscribe):
            return bool(accepted), str(reason or "")

        search_title = str(candidate.get("search_title") or "").strip()
        resource_name = str(candidate.get("name") or "").strip()
        # panlist 缺 name 时会把 search_title 回填到 candidate.name；它仍只是 discovery。
        if resource_name and search_title and resource_name.casefold() == search_title.casefold():
            resource_name = ""

        video_files = [
            str(row.get("path") or row.get("name") or "").strip()
            for row in (template.get("files") or [])
            if isinstance(row, dict)
            and _is_video(str(row.get("path") or row.get("name") or ""))
        ]
        if not video_files:
            return False, "迅雷电影真实 payload 未发现可验证的视频文件"

        aliases_fn = getattr(self, "_identity_aliases_v1111", None)
        aliases = list(
            aliases_fn(subscribe)
            if callable(aliases_fn)
            else [str(getattr(subscribe, "name", "") or "")]
        )
        primary = [
            str(info.get("title") or "").strip(),
            resource_name,
        ]
        assessment = movie_actual_match_v11219(
            aliases=aliases,
            expected_year=getattr(subscribe, "year", None),
            primary_evidences=primary,
            file_evidences=video_files,
        )
        if bool(assessment.get("ok")):
            return True, (
                "迅雷电影真实 payload 通过："
                + str(assessment.get("reason") or f"score={assessment.get('score', 0)}")[:300]
            )

        # 保留 v1.12.16 已证明安全的严格双语真实资源桥；不做其它模糊救回。
        bridge = getattr(self, "_bilingual_bridge_v11216", None)
        if callable(bridge):
            try:
                rescued, bridge_reason = bridge(subscribe, candidate, info, template)
            except Exception:
                rescued, bridge_reason = False, ""
            if rescued:
                return True, f"迅雷电影真实 payload 双语闭环通过：{str(bridge_reason or '')[:300]}"

        return False, (
            "迅雷电影真实 payload 身份拒绝："
            + str(assessment.get("reason") or "实际标题未命中 MoviePilot/TMDB 官方别名")[:320]
        )


__all__ = [
    "GuangYaMediaMatchV11219Mixin",
    "movie_actual_match_v11219",
    "source_claim_episodes_v11219",
]

media_source_v209:
"""唯一 media_source 归一化：正确识别 MoviePilot 的 themoviedb / TMDB token。

禁止再用 ``"tmdb" in source``：对 ``themoviedb`` 会得到 False。
"""
from __future__ import annotations

from typing import Any, Optional


_TMDB_TOKENS = frozenset({
    "tmdb",
    "themoviedb",
    "themoviedb.org",
    "the movie db",
    "the movie database",
})


def _enum_raw(value: Any) -> Any:
    if value is None:
        return None
    if hasattr(value, "value"):
        try:
            return getattr(value, "value")
        except Exception:
            pass
    if hasattr(value, "name") and not isinstance(value, (str, bytes)):
        # MediaSource.TMDB → name "TMDB"
        try:
            name = getattr(value, "name")
            if isinstance(name, str) and name and name == name.upper() and len(name) <= 32:
                return name
        except Exception:
            pass
    return value


def _import_mp_normalize_media_source():
    """Prefer MoviePilot app.schemas.media; fallback to types. Only ImportError."""
    try:
        from app.schemas.media import normalize_media_source  # type: ignore
        return normalize_media_source
    except ImportError:
        pass
    try:
        from app.schemas.types import normalize_media_source  # type: ignore
        return normalize_media_source
    except ImportError:
        return None


def _import_mp_media_source_enum():
    try:
        from app.schemas.types import MediaSource  # type: ignore
        return MediaSource
    except ImportError:
        try:
            from app.schemas.media import MediaSource  # type: ignore
            return MediaSource
        except ImportError:
            return None


def normalize_media_source_token(value: Any) -> str:
    """把任意 media_source 归一成小写稳定 token；TMDB 家族统一为 ``tmdb``。"""
    if value is None:
        return ""

    MediaSource = _import_mp_media_source_enum()
    normalize_media_source = _import_mp_normalize_media_source()

    if MediaSource is not None:
        try:
            tmdb_enum = getattr(MediaSource, "TMDB", None)
            if tmdb_enum is not None and value == tmdb_enum:
                return "tmdb"
        except Exception:
            pass

    if callable(normalize_media_source):
        try:
            normalized = normalize_media_source(value)
            if MediaSource is not None:
                tmdb_enum = getattr(MediaSource, "TMDB", None)
                if tmdb_enum is not None and normalized == tmdb_enum:
                    return "tmdb"
            token = str(_enum_raw(normalized) or "").strip().lower()
            if token in _TMDB_TOKENS or token.replace("_", "") in {"tmdb", "themoviedb"}:
                return "tmdb"
            if token:
                return token
        except Exception:
            pass

    raw = _enum_raw(value)
    text = str(raw or "").strip().lower()
    if not text:
        return ""
    # Exact / known aliases only — never broad ``"tmdb" in text``.
    compact = text.replace("_", "").replace("-", "").replace(" ", "")
    if text in _TMDB_TOKENS or compact in {"tmdb", "themoviedb", "themoviedb.org"}:
        return "tmdb"
    if compact == "imdb":
        return "imdb"
    if compact in {"douban", "db"}:
        return "douban"
    if compact in {"bangumi", "bgm"}:
        return "bangumi"
    if compact == "anilist":
        return "anilist"
    return text


def is_tmdb_source(value: Any) -> bool:
    """True iff value denotes TheMovieDB / TMDB media source."""
    return normalize_media_source_token(value) == "tmdb"


def is_imdb_source(value: Any) -> bool:
    return normalize_media_source_token(value) == "imdb"


__all__ = [
    "normalize_media_source_token",
    "is_tmdb_source",
    "is_imdb_source",
]

movie_bilingual_identity_v11216:
"""v1.12.16 电影双语真实资源身份桥接。

只解决一种可证明为同一媒体的误杀：搜索/订阅使用中文标题，而同一个迅雷分享的
真实顶层名称明确同时给出中文标题与第二语言标题，实际视频文件再使用这个第二语言标题。

安全边界：
- 仅电影；
- 父层已经通过则完全不介入；
- 只救回“实际资源顶层标题与订阅不一致”这一类标题冲突；
- 搜索发现必须命中订阅官方别名；
- 实际资源必须明确包含订阅年份，且不能出现其它年份或季号；
- 同一个真实顶层名称必须同时包含订阅别名段 + 第二语言标题段；
- 至少一个真实视频文件必须精确匹配该第二语言标题段；
- 不使用编辑距离、拼音、包含式模糊匹配，也不允许 discovery 单独覆盖真实资源冲突。
"""
from __future__ import annotations

import html
import re
from pathlib import PurePosixPath
from typing import Any, Dict, Iterable, List, Sequence, Set, Tuple

from .search_recall_v11217 import GuangYaSearchRecallV11217Mixin
from .media_identity_v1111 import (
    explicit_seasons_v1111,
    explicit_years_v1111,
    strong_title_match_v1111,
    title_key_v1111,
)

_YEAR_V11216 = re.compile(r"(?<!\d)(19\d{2}|20\d{2})(?!\d)")
_BRACKET_V11216 = re.compile(r"[【\[（(]([^】\]）)]{2,120})[】\]）)]")
_CJK_LATIN_SPLIT_V11216 = re.compile(
    r"(?<=[\u4e00-\u9fff])(?:\s|[·•:：\-—_/])+?(?=[A-Za-z])|"
    r"(?<=[A-Za-z])(?:\s|[·•:：\-—_/])+?(?=[\u4e00-\u9fff])"
)
_DECOR_SPLIT_V11216 = re.compile(r"(?:\|{1,2}|／|---+|={2,}|⭐+|🌈+|🎬+|\n+)")
_GENERIC_SEGMENTS_V11216 = {
    "movie", "film", "video", "resource", "share", "download", "french", "english", "chinese",
    "电影", "影片", "视频", "资源", "分享", "剧情", "传记", "动作", "喜剧", "爱情", "科幻",
}


def _clean_segment_v11216(value: Any) -> str:
    text = html.unescape(str(value or "")).replace("\\", "/").strip()
    if not text:
        return ""
    try:
        text = PurePosixPath(text).name or text
    except Exception:
        pass
    text = re.sub(r"\.(?:mkv|mp4|ts|m2ts|avi|mov|wmv|flv|webm|iso|m4v)$", "", text, flags=re.I)
    text = text.strip(" \t\r\n._-—|/\\[]【】()（）{}<>⭐🌈🎬")
    return text


def _title_segments_v11216(value: Any, expected_year: Any = None) -> List[Tuple[str, str]]:
    """抽取严格可解释的标题段；返回 (规范 key, 原始段)。"""
    raw = _clean_segment_v11216(value)
    if not raw:
        return []

    candidates: List[str] = [raw]
    candidates.extend(match.group(1).strip() for match in _BRACKET_V11216.finditer(raw))
    candidates.extend(part.strip() for part in _DECOR_SPLIT_V11216.split(raw) if part.strip())

    year = str(expected_year or "").strip()
    if year and re.fullmatch(r"(?:19|20)\d{2}", year):
        marker = re.search(rf"(?<!\d){re.escape(year)}(?!\d)", raw)
        if marker and marker.start() > 1:
            candidates.append(raw[:marker.start()].strip(" ._-—|/\\[]【】()（）"))

    expanded = list(candidates)
    for candidate in candidates:
        parts = [part.strip() for part in _CJK_LATIN_SPLIT_V11216.split(candidate) if part.strip()]
        if len(parts) == 2:
            expanded.extend(parts)

    result: List[Tuple[str, str]] = []
    seen: Set[str] = set()
    for candidate in expanded:
        cleaned = _clean_segment_v11216(candidate)
        key = title_key_v1111(cleaned, expected_year=expected_year).casefold()
        if len(key) < 3 or key in _GENERIC_SEGMENTS_V11216 or key in seen:
            continue
        seen.add(key)
        result.append((key, cleaned))
    return result


class GuangYaMovieBilingualIdentityV11216Mixin(GuangYaSearchRecallV11217Mixin):
    """用同一真实分享内的双语标题关系救回电影标题误杀。"""

    plugin_version = "1.12.16"
    build_id = "20260906-r63"

    @staticmethod
    def _known_alias_keys_v11216(aliases: Sequence[str], expected_year: Any) -> Set[str]:
        result: Set[str] = set()
        for alias in aliases or []:
            key = title_key_v1111(alias, expected_year=expected_year).casefold()
            if len(key) >= 3:
                result.add(key)
        return result

    @staticmethod
    def _discovery_matches_alias_v11216(
        aliases: Sequence[str],
        values: Iterable[Any],
        expected_year: Any,
    ) -> bool:
        for value in values or []:
            if not str(value or "").strip():
                continue
            for alias in aliases or []:
                if strong_title_match_v1111(alias, value, expected_year=expected_year):
                    return True
            segment_keys = {key for key, _ in _title_segments_v11216(value, expected_year)}
            if segment_keys.intersection(
                GuangYaMovieBilingualIdentityV11216Mixin._known_alias_keys_v11216(aliases, expected_year)
            ):
                return True
        return False

    def _bilingual_bridge_v11216(
        self,
        subscribe: Any,
        candidate: Dict[str, Any],
        info: Dict[str, Any],
        template: Dict[str, Any],
    ) -> Tuple[bool, str]:
        is_movie = getattr(self, "_identity_is_movie_v1111", None)
        if not callable(is_movie) or not bool(is_movie(subscribe)):
            return False, "非电影"

        aliases = list(self._identity_aliases_v1111(subscribe) or [])
        year = str(getattr(subscribe, "year", "") or "").strip()
        if not aliases or not year:
            return False, "缺少订阅别名或年份"

        search_title = str(candidate.get("search_title") or "").strip()
        if not self._discovery_matches_alias_v11216(
            aliases,
            [search_title, candidate.get("label")],
            year,
        ):
            return False, "搜索发现未命中订阅别名"

        resource_name = str(candidate.get("name") or "").strip()
        if resource_name and search_title and resource_name.casefold() == search_title.casefold():
            resource_name = ""
        primary = [
            str(info.get("title") or "").strip(),
            resource_name,
        ]
        files = [
            str(row.get("path") or row.get("name") or "").strip()
            for row in (template.get("files") or [])
            if isinstance(row, dict) and str(row.get("path") or row.get("name") or "").strip()
        ]
        actual = [value for value in [*primary, *files[:300]] if value]
        years = explicit_years_v1111(actual, aliases)
        if not years or years != {year}:
            return False, f"实际年份不足或冲突：期望={year} 实际={sorted(years)}"
        if explicit_seasons_v1111(actual):
            return False, "电影实际资源出现季号"

        known = self._known_alias_keys_v11216(aliases, year)
        if not known:
            return False, "订阅别名无法规范化"

        file_keys: Set[str] = set()
        for value in files:
            file_keys.update(key for key, _ in _title_segments_v11216(value, year))

        bridges: List[str] = []
        for value in primary:
            if not value:
                continue
            segments = _title_segments_v11216(value, year)
            keys = {key for key, _ in segments}
            if not keys.intersection(known):
                continue
            foreign = {key for key in keys if key not in known and len(key) >= 4}
            matched_foreign = sorted(foreign.intersection(file_keys))
            if not matched_foreign:
                continue
            bridge_key = matched_foreign[0]
            bridge_text = next((text for key, text in segments if key == bridge_key), bridge_key)
            bridges.append(bridge_text)

        if not bridges:
            return False, "同一分享未形成“订阅标题 + 第二语言标题 → 实际文件”闭环"

        return True, f"同一分享双语闭环：订阅标题 + {bridges[0]}；年份={year}；真实文件精确命中第二语言标题"

    def _xunlei_json_identity_matches_v1123(
        self,
        subscribe: Any,
        candidate: Dict[str, Any],
        info: Dict[str, Any],
        template: Dict[str, Any],
    ):
        accepted, reason = super()._xunlei_json_identity_matches_v1123(subscribe, candidate, info, template)
        if accepted:
            return accepted, reason
        text = str(reason or "")
        if "实际资源顶层标题与订阅不一致" not in text:
            return accepted, reason

        rescued, bridge_reason = self._bilingual_bridge_v11216(subscribe, candidate, info, template)
        if not rescued:
            return accepted, reason

        self._plugin_log(
            "INFO",
            "【光鸭转存助手】【电影双语身份v1.12.16】#%s %s 原硬冲突已由真实分享双语闭环救回：%s",
            int(getattr(subscribe, "id", 0) or 0),
            str(getattr(subscribe, "name", "") or ""),
            bridge_reason,
        )
        return True, f"迅雷媒体身份通过：电影双语真实资源桥接；{bridge_reason}"


