release_v1110:
"""光鸭转存助手 v1.11.0 发布层。

在 v1.10.24 跨来源集级终止栅栏之上补齐长期追更闭环：
- 每天固定执行一次“全员缺集复核”，即使当天频道没有新消息，也会重新核对所有固定路线订阅；
- 使用 MoviePilot/TMDB 的 next_episode_to_air 生成下一集更新日历；
- 日历中今天、昨天或明天播出的剧，每小时进入一次轻量到期检查，单订阅至少间隔 2 小时，兼顾提前放出；
- 所有日历/全员复核仍经过现有缺集、在途 reservation、成功集终态与质量门禁，不会绕过 v1.10.24 防重复。
"""
from __future__ import annotations

import datetime
from typing import Any, Dict, List, Optional

from apscheduler.triggers.cron import CronTrigger

from app.chain.media import MediaChain
from app.schemas.types import MediaSource, MediaType

from .media_source_v209 import is_tmdb_source


class GuangYaReleaseV1110Mixin:
    """v1.11.0 更新日历 + 每日全员补漏。"""

    plugin_version = "1.11.0"
    build_id = "20260903-r41"
    _daily_catchup_cron_v1110 = "10 4 * * *"
    _calendar_refresh_hours_v1110 = 6
    _calendar_due_check_minutes_v1110 = 60
    _calendar_per_sub_cooldown_hours_v1110 = 2
    _calendar_due_limit_v1110 = 20

    def get_service(self) -> List[Dict[str, Any]]:
        services = list(super().get_service() or [])
        if not self._enabled:
            return services
        try:
            catchup_trigger = CronTrigger.from_crontab(self._daily_catchup_cron_v1110)
        except Exception:
            catchup_trigger = CronTrigger.from_crontab("10 4 * * *")
        services.append({
            "id": "GuangYaTransferAssistantDailyCatchup",
            "name": "光鸭转存助手每日全员缺集复核",
            "trigger": catchup_trigger,
            "func": self._daily_full_catchup_v1110,
            "kwargs": {},
        })
        services.append({
            "id": "GuangYaTransferAssistantAiringDue",
            "name": "光鸭转存助手更新日历到期检查",
            "trigger": "interval",
            "func": self._calendar_due_check_v1110,
            "kwargs": {"minutes": self._calendar_due_check_minutes_v1110},
        })
        return services

    @staticmethod
    def _next_episode_value_v1110(next_episode: Any, field: str, default: Any = None) -> Any:
        if isinstance(next_episode, dict):
            return next_episode.get(field, default)
        return getattr(next_episode, field, default)

    @staticmethod
    def _parse_iso_date_v1110(value: Any) -> Optional[datetime.date]:
        text = str(value or "").strip()[:10]
        if not text:
            return None
        try:
            return datetime.date.fromisoformat(text)
        except ValueError:
            return None

    def _subscription_tmdb_id_v1110(self, subscribe: Any) -> str:
        direct = getattr(subscribe, "tmdbid", None) or getattr(subscribe, "tmdb_id", None)
        if direct not in (None, ""):
            return str(direct)
        if not is_tmdb_source(getattr(subscribe, "media_source", None)):
            return ""
        media_id = getattr(subscribe, "mediaid", None) or getattr(subscribe, "media_id", None)
        return str(media_id or "").strip()

    def _airing_calendar_stale_v1110(self) -> bool:
        payload = self.get_data("airing_calendar_v1110") or {}
        try:
            updated = datetime.datetime.fromisoformat(str(payload.get("updated_at") or ""))
        except (TypeError, ValueError):
            return True
        return datetime.datetime.now() - updated >= datetime.timedelta(hours=self._calendar_refresh_hours_v1110)

    def _refresh_airing_calendar_v1110(self, force: bool = False) -> Dict[str, Any]:
        """从 MoviePilot 的统一媒体信息读取 TMDB 下一集播出摘要。"""
        current = self.get_data("airing_calendar_v1110") or {}
        if not force and current and not self._airing_calendar_stale_v1110():
            return current

        selected = set(int(value) for value in (self._selected_subscriptions or []) if str(value).isdigit())
        rows: List[Dict[str, Any]] = []
        errors: List[str] = []
        chain = MediaChain()
        for subscribe in self._list_subscriptions(None) or []:
            sid = int(getattr(subscribe, "id", 0) or 0)
            if sid not in selected or self._is_movie_subscription(subscribe):
                continue
            if str(getattr(subscribe, "state", "") or "") not in {"N", "R"}:
                continue
            tmdb_id = self._subscription_tmdb_id_v1110(subscribe)
            if not tmdb_id:
                continue
            try:
                try:
                    recognize = getattr(self, "_recognize_media_cached_v208", None)
                    if callable(recognize):
                        info = recognize(
                            mtype=MediaType.TV,
                            media_source=MediaSource.TMDB,
                            media_id=tmdb_id,
                            cache=not force,
                        )
                    else:
                        info = chain.recognize_media(
                            mtype=MediaType.TV,
                            media_source=MediaSource.TMDB,
                            media_id=tmdb_id,
                            cache=not force,
                        )
                except TypeError:
                    recognize = getattr(self, "_recognize_media_cached_v208", None)
                    if callable(recognize):
                        info = recognize(
                            mtype=MediaType.TV,
                            media_source=MediaSource.TMDB,
                            media_id=tmdb_id,
                        )
                    else:
                        info = chain.recognize_media(
                            mtype=MediaType.TV,
                            media_source=MediaSource.TMDB,
                            media_id=tmdb_id,
                        )
            except Exception as err:
                errors.append(f"#{sid} {getattr(subscribe, 'name', '')}: {str(err)[:160]}")
                continue
            if not info:
                continue
            next_episode = getattr(info, "next_episode_to_air", None)
            if not next_episode:
                continue
            air_date = str(self._next_episode_value_v1110(next_episode, "air_date", "") or "")
            episode = int(self._next_episode_value_v1110(next_episode, "episode_number", 0) or 0)
            season = int(self._next_episode_value_v1110(next_episode, "season_number", 0) or 0)
            if not air_date or episode <= 0:
                continue
            missing = list(self._subscription_missing_episodes(subscribe) or [])
            rows.append({
                "subscribe_id": sid,
                "name": str(getattr(subscribe, "name", "") or getattr(info, "title", "") or ""),
                "year": str(getattr(subscribe, "year", "") or getattr(info, "year", "") or ""),
                "tmdb_id": tmdb_id,
                "season": season or int(getattr(subscribe, "season", 0) or 0),
                "episode": episode,
                "air_date": air_date[:10],
                "missing": missing,
                "target_missing": episode in set(int(value) for value in missing if int(value or 0) > 0),
            })

        rows.sort(key=lambda row: (str(row.get("air_date") or "9999-99-99"), str(row.get("name") or "")))
        payload = {
            "updated_at": datetime.datetime.now().isoformat(timespec="seconds"),
            "count": len(rows),
            "items": rows,
            "errors": errors[:30],
        }
        self.save_data("airing_calendar_v1110", payload)
        self._plugin_log(
            "INFO",
            "【光鸭转存助手】【更新日历】已刷新 %s 个下一集计划，异常=%s",
            len(rows),
            len(errors),
        )
        return payload

    def _calendar_due_rows_v1110(self, payload: Dict[str, Any]) -> List[Dict[str, Any]]:
        today = datetime.date.today()
        earliest = today - datetime.timedelta(days=1)
        latest = today + datetime.timedelta(days=1)
        due: List[Dict[str, Any]] = []
        for row in payload.get("items") or []:
            if not isinstance(row, dict):
                continue
            air_date = self._parse_iso_date_v1110(row.get("air_date"))
            if not air_date or air_date < earliest or air_date > latest:
                continue
            due.append(dict(row))
        due.sort(key=lambda row: (str(row.get("air_date") or ""), int(row.get("subscribe_id") or 0)))
        return due[:self._calendar_due_limit_v1110]

    def _calendar_due_check_v1110(self) -> Dict[str, Any]:
        """对临近播出订阅做有限频率的强制补漏，覆盖“官方日期前提前放出”的情况。"""
        payload = self._refresh_airing_calendar_v1110(force=False)
        due = self._calendar_due_rows_v1110(payload)
        state = self.get_data("airing_check_state_v1110") or {}
        if not isinstance(state, dict):
            state = {}
        now = datetime.datetime.now()
        checked = 0
        skipped = 0
        results: List[Dict[str, Any]] = []
        for row in due:
            sid = int(row.get("subscribe_id") or 0)
            subscribe = self._find_subscription(sid)
            if not subscribe or not self._is_guangya_route(subscribe):
                continue
            missing = list(self._subscription_missing_episodes(subscribe) or [])
            episode = int(row.get("episode") or 0)
            if episode > 0 and missing and episode not in set(int(value) for value in missing if int(value or 0) > 0):
                skipped += 1
                continue
            last_text = str((state.get(str(sid)) or {}).get("checked_at") or "") if isinstance(state.get(str(sid)), dict) else ""
            try:
                last = datetime.datetime.fromisoformat(last_text)
            except (TypeError, ValueError):
                last = None
            if last and now - last < datetime.timedelta(hours=self._calendar_per_sub_cooldown_hours_v1110):
                skipped += 1
                continue
            try:
                result = self._try_transfer_subscription(subscribe, force=True, refresh_channel=False)
                results.append({"subscribe_id": sid, "episode": episode, "air_date": row.get("air_date"), "success": bool(result.get("success")), "message": result.get("message") or ""})
            except Exception as err:
                results.append({"subscribe_id": sid, "episode": episode, "air_date": row.get("air_date"), "success": False, "message": str(err)[:300]})
            state[str(sid)] = {"checked_at": now.isoformat(timespec="seconds"), "episode": episode, "air_date": row.get("air_date")}
            checked += 1
        self.save_data("airing_check_state_v1110", state)
        if checked:
            self._plugin_log("INFO", "【光鸭转存助手】【更新日历】到期检查完成：检查=%s 跳过=%s", checked, skipped)
        return {"success": True, "checked": checked, "skipped": skipped, "results": results}

    def _daily_full_catchup_v1110(self) -> Dict[str, Any]:
        """每天一次全员复核：不依赖是否有新频道消息，逐个核对真实缺集并重新匹配。"""
        started = datetime.datetime.now()
        try:
            self.refresh_channels(force=True)
        except Exception as err:
            self._plugin_log("WARNING", "【光鸭转存助手】【每日全员复核】频道强制刷新失败，继续使用缓存/其它来源：%s", err)
        try:
            self._refresh_airing_calendar_v1110(force=True)
        except Exception as err:
            self._plugin_log("WARNING", "【光鸭转存助手】【每日全员复核】更新日历刷新失败：%s", err)

        results: List[Dict[str, Any]] = []
        selected = list(dict.fromkeys(int(value) for value in (self._selected_subscriptions or []) if str(value).isdigit()))
        for sid in selected:
            subscribe = self._find_subscription(sid)
            if not subscribe or not self._is_guangya_route(subscribe):
                continue
            if str(getattr(subscribe, "state", "") or "") not in {"N", "R"}:
                continue
            try:
                sync = getattr(self, "_sync_media_library_progress", None)
                if callable(sync):
                    sync(subscribe)
            except Exception:
                pass
            fresh = self._find_subscription(sid) or subscribe
            before = [] if self._is_movie_subscription(fresh) else list(self._subscription_missing_episodes(fresh) or [])
            try:
                result = self._try_transfer_subscription(fresh, force=True, refresh_channel=False)
                success = bool(result.get("success"))
                message = str(result.get("message") or "")
            except Exception as err:
                success = False
                message = str(err)[:400]
            latest = self._find_subscription(sid) or fresh
            after = [] if self._is_movie_subscription(latest) else list(self._subscription_missing_episodes(latest) or [])
            results.append({
                "subscribe_id": sid,
                "name": str(getattr(latest, "name", "") or ""),
                "missing_before": before,
                "missing_after": after,
                "success": success,
                "message": message,
            })

        payload = {
            "started_at": started.isoformat(timespec="seconds"),
            "finished_at": datetime.datetime.now().isoformat(timespec="seconds"),
            "checked": len(results),
            "changed": sum(1 for row in results if row.get("missing_before") != row.get("missing_after")),
            "failed": sum(1 for row in results if not row.get("success")),
            "results": results[-200:],
        }
        self.save_data("daily_catchup_v1110", payload)
        self._plugin_log(
            "INFO",
            "【光鸭转存助手】【每日全员复核】完成：订阅=%s 缺集变化=%s 执行未成功=%s",
            payload["checked"], payload["changed"], payload["failed"],
        )
        return {"success": True, "data": payload, "message": f"已复核 {payload['checked']} 个固定路线订阅"}

    def get_page(self):
        pages = list(super().get_page() or [])
        calendar = self.get_data("airing_calendar_v1110") or {}
        catchup = self.get_data("daily_catchup_v1110") or {}
        rows = []
        for row in (calendar.get("items") or [])[:30]:
            if not isinstance(row, dict):
                continue
            rows.append({
                "component": "VListItem",
                "props": {
                    "title": f"{row.get('air_date') or '-'} · {row.get('name') or '-'} · S{int(row.get('season') or 0):02d}E{int(row.get('episode') or 0):02d}",
                    "subtitle": (
                        f"订阅 #{row.get('subscribe_id')} · TMDB {row.get('tmdb_id') or '-'} · "
                        f"当前缺集 {','.join('E%02d' % int(value) for value in (row.get('missing') or [])[:12]) or '无'}"
                    ),
                },
            })
        card = {
            "component": "VCard",
            "props": {"variant": "outlined", "class": "mb-3"},
            "content": [
                {"component": "VCardTitle", "text": "追更日历与每日补漏"},
                {"component": "VCardText", "text": (
                    f"更新日历：{calendar.get('updated_at') or '尚未生成'} · 下一集计划 {calendar.get('count') or 0} 个。"
                    f" 每天 04:10 自动全员复核一次；临近播出（昨天/今天/明天）每小时检查，单订阅至少间隔 2 小时。"
                    f" 最近全员复核：{catchup.get('finished_at') or '-'} · 检查 {catchup.get('checked') or 0} · 缺集变化 {catchup.get('changed') or 0}。"
                )},
                {"component": "VList", "props": {"density": "compact", "style": "max-height: 420px; overflow-y: auto;"}, "content": rows or [{"component": "VListItem", "props": {"title": "暂无 TMDB 下一集播出计划；每日全员复核仍会正常执行"}}]},
            ],
        }
        return [card, *pages]


__all__ = ["GuangYaReleaseV1110Mixin"]

reliability_v170:
"""光鸭转存助手 v1.7.0 上线可靠性层。

集中解决三类真实运行问题：
1. 高频 search / API / 消息触发时的后台检查合并与同订阅最多一次补偿重查；
2. 插件热更新/重载后旧实例仍残留事件回调或后台线程时，只允许最新实例继续工作；
3. Telegram 镜像/频道源临时不可用时进入缓存降级 + 指数退避，并自动恢复检查。
"""

from __future__ import annotations

import threading
import time
import weakref
from typing import Any, Dict, Iterable, List

from app.chain.subscribe import SubscribeChain
from app.sdk.events import Event, eventmanager
from app.schemas.types import EventType


class GuangYaReliabilityMixin:
    """必须位于 GuangYaExperienceMixin 之前的最终可靠性 mixin。"""

    build_id = "20260824-r5"
    _channel_retry_base_seconds = 30.0
    _channel_retry_max_seconds = 900.0

    def _ensure_reliability_state(self) -> None:
        if not hasattr(self, "_reliability_lock"):
            self._reliability_lock = threading.RLock()
        if not hasattr(self, "_channel_refresh_lock"):
            self._channel_refresh_lock = threading.Lock()
        if not hasattr(self, "_async_route_active"):
            self._async_route_active: set[int] = set()
        if not hasattr(self, "_async_route_recheck"):
            self._async_route_recheck: set[int] = set()
        if not hasattr(self, "_channel_recovery_timer"):
            self._channel_recovery_timer = None

    def _claim_runtime_owner(self) -> None:
        """把所有热重载实例的唯一所有权锚定到 MoviePilot 稳定类对象上。"""
        self._runtime_generation = f"{time.time_ns()}-{id(self)}"
        SubscribeChain._guangya_runtime_owner_ref = weakref.ref(self)
        SubscribeChain._guangya_runtime_generation = self._runtime_generation

    def _runtime_is_current(self) -> bool:
        ref = getattr(SubscribeChain, "_guangya_runtime_owner_ref", None)
        owner = ref() if callable(ref) else None
        return owner is self and str(getattr(SubscribeChain, "_guangya_runtime_generation", "")) == str(
            getattr(self, "_runtime_generation", "")
        )

    def init_plugin(self, config: dict = None) -> None:
        self._ensure_reliability_state()
        previous_ref = getattr(SubscribeChain, "_guangya_runtime_owner_ref", None)
        previous_generation = getattr(SubscribeChain, "_guangya_runtime_generation", "")
        self._claim_runtime_owner()
        try:
            super().init_plugin(config)
        except Exception:
            # 初始化失败不能让坏实例抢占运行所有权。
            SubscribeChain._guangya_runtime_owner_ref = previous_ref
            SubscribeChain._guangya_runtime_generation = previous_generation
            raise
        self._record_route_health(
            runtime_owner=True,
            runtime_generation=self._runtime_generation,
            runtime_started_at=self._now_text(),
            build=self.build_id,
        )

    @eventmanager.register(EventType.PluginAction)
    def action_event_handler(self, event: Event) -> None:
        """热重载后旧实例即使残留回调，也不再处理旧版消息 action。"""
        if not self._runtime_is_current():
            return
        return super().action_event_handler(event)

    @eventmanager.register(EventType.PluginAction)
    def experience_action_event_handler(self, event: Event) -> None:
        """热重载后旧实例即使残留回调，也不再处理体验层消息 action。"""
        if not self._runtime_is_current():
            return
        return super().experience_action_event_handler(event)

    def _cached_channel_items(self) -> List[Dict[str, Any]]:
        index = self.get_data("channel_index") or {}
        return list(index.get("items") or [])

    def _channel_outage_state(self) -> Dict[str, Any]:
        return dict(self.get_data("channel_outage") or {})

    def _schedule_channel_recovery(self, delay: float) -> None:
        """频道故障后即使没有新的 MP 搜索事件，也会在退避到期后自动尝试恢复。"""
        self._ensure_reliability_state()
        delay = max(1.0, float(delay or 1.0))
        with self._reliability_lock:
            current = self._channel_recovery_timer
            if current and current.is_alive():
                return

            def recover() -> None:
                try:
                    if not self._runtime_is_current() or not self._enabled:
                        return
                    ids = list(sorted(set(int(v) for v in self._selected_subscriptions if int(v or 0) > 0)))
                    if ids:
                        self._plugin_log(
                            "INFO",
                            "【光鸭转存助手】【频道恢复】退避时间已到，自动重新检查 %s 个固定转存订阅",
                            len(ids),
                        )
                        self._queue_async_route_check(ids, trigger="频道故障自动恢复")
                    else:
                        # 没有固定订阅时也刷新一次索引，恢复频道健康状态。
                        self.refresh_channels(force=True)
                finally:
                    with self._reliability_lock:
                        self._channel_recovery_timer = None

            timer = threading.Timer(delay, recover)
            timer.daemon = True
            self._channel_recovery_timer = timer
            timer.start()

    def refresh_channels(self, force: bool = False):
        """频道刷新单飞 + 故障熔断。

        - 同一进程只允许一个频道刷新在跑，其它调用直接复用缓存；
        - 全源失败时保留旧索引，不把固定转存误回退到本地下载；
        - 指数退避后自动恢复，避免镜像故障时被高频 search 打爆。
        """
        self._ensure_reliability_state()
        now = time.time()
        outage = self._channel_outage_state()
        try:
            retry_after = float(outage.get("retry_after") or 0)
        except (TypeError, ValueError):
            retry_after = 0.0
        if retry_after > now:
            wait = max(1, int(retry_after - now))
            self._record_route_health(
                channel_degraded=True,
                channel_retry_after=retry_after,
                channel_retry_seconds=wait,
            )
            return self._cached_channel_items()

        if not self._channel_refresh_lock.acquire(blocking=False):
            self._record_route_health(channel_refresh_coalesced_at=self._now_text())
            return self._cached_channel_items()

        try:
            try:
                entries = super().refresh_channels(force=force)
            except Exception as err:
                last_run = {"success": False, "errors": [str(err)]}
                entries = self._cached_channel_items()
            else:
                last_run = self.get_data("last_run") or {}

            if bool(last_run.get("success")):
                previous_failures = int(outage.get("failures") or 0)
                self.save_data("channel_outage", {
                    "state": "healthy",
                    "failures": 0,
                    "recovered_at": self._now_text(),
                    "retry_after": 0,
                })
                self._record_route_health(
                    channel_degraded=False,
                    channel_failures=0,
                    channel_recovered_at=self._now_text(),
                )
                if previous_failures:
                    self._plugin_log(
                        "INFO",
                        "【光鸭转存助手】【频道恢复】频道源已恢复，结束缓存降级模式（此前连续失败 %s 次）",
                        previous_failures,
                    )
                return entries

            failures = max(1, int(outage.get("failures") or 0) + 1)
            delay = min(
                self._channel_retry_max_seconds,
                self._channel_retry_base_seconds * (2 ** min(failures - 1, 5)),
            )
            retry_at = time.time() + delay
            errors = last_run.get("errors") or []
            self.save_data("channel_outage", {
                "state": "degraded",
                "failures": failures,
                "since": outage.get("since") or self._now_text(),
                "last_failure": self._now_text(),
                "retry_after": retry_at,
                "retry_seconds": int(delay),
                "errors": list(errors)[-5:],
                "cached_items": len(self._cached_channel_items()),
            })
            self._record_route_health(
                channel_degraded=True,
                channel_failures=failures,
                channel_retry_after=retry_at,
            )
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【频道降级】频道源连续失败 %s 次，继续使用本地缓存；%s 秒后自动重试，不回退本地下载",
                failures,
                int(delay),
            )
            self._schedule_channel_recovery(delay)
            return entries or self._cached_channel_items()
        finally:
            self._channel_refresh_lock.release()

    def _run_reliability_route_batch(self, batch: List[int], trigger: str) -> None:
        subscriptions = []
        need_refresh = False
        for sid in batch:
            if not self._runtime_is_current() or not self._enabled:
                return
            subscribe = self._find_subscription(sid)
            if not subscribe or not self._is_guangya_route(subscribe):
                continue
            subscriptions.append(subscribe)
            try:
                if not self._cached_matches_for_subscription(subscribe):
                    need_refresh = True
            except Exception:
                need_refresh = True

        if need_refresh and subscriptions:
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【后台合并】%s：%s 个订阅统一执行一次频道检查",
                trigger,
                len(subscriptions),
            )
            self.refresh_channels(force=True)

        try:
            self._inspect_cache.clear()
        except Exception:
            pass

        for subscribe in subscriptions:
            if not self._runtime_is_current() or not self._enabled:
                return
            sid = int(getattr(subscribe, "id", 0) or 0)
            try:
                result = self._try_transfer_subscription(subscribe, refresh_channel=False)
                message = str(result.get("message") or "检查完成")
                self._record_route_health(
                    last_route_result=message[:500],
                    last_route_result_at=self._now_text(),
                    last_async_check_id=sid,
                    last_async_trigger=trigger,
                )
                self._plugin_log(
                    "INFO",
                    "【光鸭转存助手】【后台检查】#%s %s：%s",
                    sid,
                    getattr(subscribe, "name", ""),
                    message,
                )
            except Exception as err:
                self._plugin_log(
                    "EXCEPTION",
                    "【光鸭转存助手】【后台检查】#%s %s 异常：%s",
                    sid,
                    getattr(subscribe, "name", ""),
                    err,
                )

    def _queue_async_route_check(self, sids: Iterable[int], trigger: str = "后台检查") -> None:
        """可靠的后台检查合并器：同一订阅执行期间最多只保留一次补偿重查。"""
        self._ensure_reliability_state()
        ids = {
            int(value) for value in sids
            if str(value).isdigit() and int(value) > 0
        }
        if not ids or not self._enabled or not self._runtime_is_current():
            return

        with self._async_route_lock:
            active_hits = ids.intersection(self._async_route_active)
            if active_hits:
                self._async_route_recheck.update(active_hits)
            self._async_route_pending.update(ids - active_hits)
            if self._async_route_worker_running:
                return
            if not self._async_route_pending:
                return
            self._async_route_worker_running = True

        def worker() -> None:
            try:
                time.sleep(float(getattr(self, "_async_route_debounce", 0.25) or 0.25))
                while self._enabled and self._runtime_is_current():
                    with self._async_route_lock:
                        batch = sorted(self._async_route_pending)
                        self._async_route_pending.clear()
                        self._async_route_active = set(batch)
                    if not batch:
                        break

                    self._run_reliability_route_batch(batch, trigger)

                    with self._async_route_lock:
                        self._async_route_active.clear()
                        if self._async_route_recheck:
                            self._async_route_pending.update(self._async_route_recheck)
                            self._async_route_recheck.clear()
                        has_more = bool(self._async_route_pending)
                    if not has_more:
                        break
                    time.sleep(0.05)
            finally:
                relaunch: List[int] = []
                with self._async_route_lock:
                    self._async_route_active.clear()
                    self._async_route_worker_running = False
                    if self._async_route_recheck:
                        self._async_route_pending.update(self._async_route_recheck)
                        self._async_route_recheck.clear()
                    if self._async_route_pending and self._enabled and self._runtime_is_current():
                        relaunch = sorted(self._async_route_pending)
                # 关键修复：补偿启动必须带真实 ID，不能用空列表，否则队列会永久卡住。
                if relaunch:
                    self._queue_async_route_check(relaunch, trigger="后台合并补偿")

        threading.Thread(target=worker, name="GuangYaReliableRouteCheck", daemon=True).start()

    def _diagnose_subscription(self, subscribe: Any) -> Dict[str, Any]:
        row = dict(super()._diagnose_subscription(subscribe))
        outage = self._channel_outage_state()
        if str(outage.get("state") or "") == "degraded" and not row.get("pending_jobs"):
            try:
                retry_after = float(outage.get("retry_after") or 0)
                wait = max(0, int(retry_after - time.time()))
            except (TypeError, ValueError):
                wait = 0
            if not row.get("matches"):
                row["reason"] = (
                    f"频道源暂时不可用，正在使用本地缓存降级；约 {wait} 秒后自动恢复检查。"
                    "固定分流仍生效，不会因此转为本地下载"
                )
                row["severity"] = "warning"
        return row

    def _build_selfcheck(self) -> Dict[str, Any]:
        report = dict(super()._build_selfcheck())
        checks = list(report.get("checks") or [])
        owner_ok = self._runtime_is_current()
        checks.append({
            "key": "runtime_owner",
            "label": "热重载实例所有权",
            "ok": owner_ok,
            "detail": "当前实例为唯一运行所有者" if owner_ok else "当前实例已被新版本替代",
            "critical": True,
        })
        outage = self._channel_outage_state()
        degraded = str(outage.get("state") or "") == "degraded"
        if degraded:
            try:
                wait = max(0, int(float(outage.get("retry_after") or 0) - time.time()))
            except (TypeError, ValueError):
                wait = 0
            detail = (
                f"缓存降级中，连续失败 {int(outage.get('failures') or 0)} 次，"
                f"缓存 {int(outage.get('cached_items') or 0)} 条，约 {wait} 秒后自动重试"
            )
        else:
            detail = "频道刷新健康，故障熔断未触发"
        checks.append({
            "key": "channel_circuit",
            "label": "频道故障降级/恢复",
            "ok": not degraded,
            "detail": detail,
            "critical": False,
        })
        report["checks"] = checks
        report["healthy"] = not any(item.get("critical") and not item.get("ok") for item in checks)
        report["build"] = self.build_id
        report["channel_degraded"] = degraded
        return report

    def get_page(self):
        pages = list(super().get_page() or [])
        outage = self._channel_outage_state()
        if str(outage.get("state") or "") != "degraded":
            return pages
        try:
            wait = max(0, int(float(outage.get("retry_after") or 0) - time.time()))
        except (TypeError, ValueError):
            wait = 0
        alert = {
            "component": "VAlert",
            "props": {
                "type": "warning",
                "variant": "tonal",
                "class": "mb-3",
                "title": "频道源暂时不可用 · 已进入缓存降级",
                "text": (
                    f"连续失败 {int(outage.get('failures') or 0)} 次，仍保留本地频道索引，"
                    f"约 {wait} 秒后自动重试。光鸭固定分流和本地下载断路器继续生效，不会静默回退。"
                ),
            },
        }
        return [alert, *pages]

    def stop_service(self) -> None:
        self._ensure_reliability_state()
        with self._reliability_lock:
            timer = self._channel_recovery_timer
            self._channel_recovery_timer = None
        if timer and timer.is_alive():
            try:
                timer.cancel()
            except Exception:
                pass
        current = self._runtime_is_current()
        try:
            return super().stop_service()
        finally:
            if current and self._runtime_is_current():
                SubscribeChain._guangya_runtime_owner_ref = None
                SubscribeChain._guangya_runtime_generation = ""


__all__ = ["GuangYaReliabilityMixin"]

resource_inbox_v209:
"""2.0.9：统一消息资源提取 + Resource Inbox（RAW HTML 优先，先于 legacy）。"""
from __future__ import annotations

import hashlib
import html
import re
import time
from typing import Any, Dict, Iterable, List, Optional, Tuple
from urllib.parse import parse_qs, unquote, urlparse

from .source_types_v180 import normalize_source_uri
from .transfer_diag_v209 import stable_trace_id


_INBOX_KEY = "channel_resource_inbox_v1"
_INBOX_RETENTION_SECONDS = 7 * 24 * 3600
_INBOX_MAX_ROWS = 5000
_DECODE_MAX_CHARS = 2_000_000
_WRAP_MAX_DEPTH = 3

_ATTR_URL_RE = re.compile(
    r"(?i)\b(?:href|data-href|data-url|data-link|data-button-url|data-clipboard-text|"
    r"data-clipboard|data-copy|data-target-url|data-share-url|onclick|value)\s*=\s*([\"'])(.*?)\1"
)
_JS_URL_RE = re.compile(
    r"(?i)(?:window\.open|location\.href\s*=|location\.assign)\s*\(\s*([\"'])(.*?)\1|"
    r"location\.href\s*=\s*([\"'])(.*?)\3"
)
_JSON_URL_RE = re.compile(
    r"(?i)[\"'](?:url|href|link|shareUrl|share_url|downloadUrl|download_url)[\"']\s*:\s*[\"']([^\"']+)[\"']"
)
_WRAP_KEYS = ("url", "target", "redirect", "redirect_uri", "link", "u")
_GUANGYA_HOSTS = frozenset({
    "guangyapan.com",
    "www.guangyapan.com",
    "guangyunav.com",
    "www.guangyunav.com",
})
_GUANGYA_RE = re.compile(
    r"https?://(?:www\.)?(?:guangyapan|guangyunav)\.com/[^\s\"'<>]+",
    re.I,
)
_XUNLEI_RE = re.compile(r"https?://pan\.xunlei\.com/[^\s\"'<>]+", re.I)
_MAGNET_RE = re.compile(r"magnet:\?[^\s\"'<>]+", re.I)
# ED2K filename may contain spaces / CJK / punctuation — do not truncate on whitespace.
_ED2K_RE = re.compile(
    r"ed2k://\|file\|[^|]+\|\d+\|[0-9A-Fa-f]{32}\|/?",
    re.I,
)
_OTHER_HOST_RE = re.compile(
    r"https?://(?:(?:www\.)?(?:115cdn\.com|115\.com|anxia\.com|quark\.cn|pan\.quark\.cn|"
    r"pan\.baidu\.com|aliyundrive\.com|www\.aliyundrive\.com|alipan\.com|www\.alipan\.com|"
    r"123pan\.com|www\.123pan\.com|drive\.uc\.cn)[^\s\"'<>]*)",
    re.I,
)
_PWD_IN_URL_RE = re.compile(r"(?i)[?&](?:pwd|passcode|password|code)=([A-Za-z0-9]{3,12})")
_LABELLED_TITLE_RE = re.compile(
    r"(?im)(?:^|\n)\s*(?:名称|片名|剧名|标题)\s*[：:]\s*([^\n]{2,320})"
)
_SERIES_EMOJI_RE = re.compile(r"(?im)(?:^|\n)\s*(?:📺\s*)?剧集\s*[：:]\s*([^\n]{2,320})")
_MOVIE_EMOJI_RE = re.compile(r"(?im)(?:^|\n)\s*(?:🎬\s*)?电影\s*[：:]\s*([^\n]{2,320})")
_YEAR_RE = re.compile(r"[（(]\s*((?:19|20)\d{2})\s*[）)]|\b((?:19|20)\d{2})\b")
_SEASON_RE = re.compile(r"(?i)\bS(?:eason)?[ ._\-]*0*(\d{1,2})\b|第\s*0*(\d{1,2})\s*季")
_EPISODE_RE = re.compile(
    r"(?i)\bS\d{1,2}\s*E(?:pisode)?[ ._\-]*0*(\d{1,4})\b|"
    r"\bE(?:P|pisode)?[ ._\-]*0*(\d{1,4})\b|"
    r"更至\s*EP?\s*0*(\d{1,4})|"
    r"第\s*0*(\d{1,4})\s*集"
)
_TOTAL_EP_RE = re.compile(r"(?:〖|^|\s)(\d{1,4})\s*集全|全\s*(\d{1,4})\s*集|共\s*(\d{1,4})\s*集")
_TMDB_RE = re.compile(r"(?i)\bTMDB\s*(?:ID)?\s*[：:#]?\s*(\d{2,9})")
_QUALITY_NOISE = re.compile(
    r"(?i)\b(?:2160p|1080p|720p|4k|8k|hdr|dv|web[- ]?dl|webrip|bluray|remux|hevc|x265|x264|高码率|中字)\b"
)


def _is_guangya_host(url: str) -> bool:
    try:
        host = (urlparse(url).hostname or "").lower()
    except Exception:
        return False
    if not host:
        return False
    if host in _GUANGYA_HOSTS:
        return True
    return host.endswith(".guangyapan.com") or host.endswith(".guangyunav.com")


def _guangya_identity(url: str) -> str:
    path = ""
    try:
        parsed = urlparse(str(url or "").split("#", 1)[0])
        path = parsed.path or ""
    except Exception:
        path = str(url or "").split("?", 1)[0].split("#", 1)[0]
    parts = [p for p in path.split("/") if p]
    if len(parts) >= 2 and parts[-2].lower() in {"s", "share"}:
        return parts[-1].split("?")[0]
    return (parts[-1] if parts else "").split("?")[0]


def _normalize_guangya_uri(raw: str) -> str:
    text = str(raw or "").split("#", 1)[0].strip()
    if "guangyapan.com" in text.lower():
        try:
            from .legacy import _canonical_share_url
            canonical = _canonical_share_url(text)
            if canonical:
                return canonical
        except Exception:
            pass
    try:
        parsed = urlparse(text)
        if parsed.scheme and parsed.netloc and parsed.path:
            return f"{parsed.scheme}://{parsed.netloc}{parsed.path}".rstrip("/")
    except Exception:
        pass
    return text


def _decode_blob(value: Any) -> str:
    current = html.unescape(str(value or ""))
    if len(current) > _DECODE_MAX_CHARS:
        current = current[:_DECODE_MAX_CHARS]
    current = current.replace("\\/", "/").replace("\\u002F", "/").replace("\\u002f", "/")
    for _ in range(3):
        decoded = unquote(current)
        if decoded == current:
            break
        current = decoded
        if len(current) > _DECODE_MAX_CHARS:
            current = current[:_DECODE_MAX_CHARS]
            break
    return current


def _unwrap_redirect(url: str, depth: int = 0) -> str:
    text = str(url or "").strip()
    if not text or depth >= _WRAP_MAX_DEPTH or len(text) > 8000:
        return text
    try:
        parsed = urlparse(text)
    except Exception:
        return text
    if not parsed.query:
        return text
    params = parse_qs(parsed.query)
    for key in _WRAP_KEYS:
        values = params.get(key) or []
        if not values:
            continue
        inner = _decode_blob(values[0])
        if inner and inner != text and (
            inner.startswith("http")
            or inner.startswith("magnet:")
            or inner.lower().startswith("ed2k:")
        ):
            return _unwrap_redirect(inner, depth + 1)
    return text


def _classify_other_url(url: str) -> Optional[Dict[str, str]]:
    raw = _unwrap_redirect(_decode_blob(url))
    if not raw.lower().startswith("http"):
        return None
    try:
        host = (urlparse(raw).hostname or "").lower()
    except Exception:
        return None
    label = ""
    if "115" in host or host.endswith("anxia.com"):
        label = "115"
    elif "quark" in host:
        label = "quark"
    elif "baidu" in host:
        label = "baidu"
    elif "aliyun" in host or "alipan" in host:
        label = "aliyun"
    elif "123pan" in host:
        label = "123"
    elif "uc.cn" in host:
        label = "uc"
    if not label:
        return None
    return {"kind": label, "uri": raw.split("#", 1)[0][:800], "actionable": "false"}


def _classify_protocol(url: str) -> Tuple[str, str, str]:
    """Return (type, uri, identity). type empty if unsupported."""
    raw = _unwrap_redirect(_decode_blob(url))
    if not raw:
        return "", "", ""
    lower = raw.lower()
    if lower.startswith("magnet:"):
        try:
            normalized = normalize_source_uri(raw)
            return "magnet", str(normalized.get("uri") or raw), str(normalized.get("identity") or "")
        except Exception:
            matched = re.search(r"(?i)urn:btih:([0-9a-z]+)", raw)
            identity = (matched.group(1).lower() if matched else raw[:80])
            return "magnet", raw, identity
    if lower.startswith("ed2k:"):
        try:
            normalized = normalize_source_uri(raw)
            return "ed2k", str(normalized.get("uri") or raw), str(normalized.get("identity") or "")
        except Exception:
            parts = raw.split("|")
            digest = parts[4].lower() if len(parts) >= 5 else raw[:80]
            return "ed2k", raw, digest
    if _is_guangya_host(raw):
        uri = _normalize_guangya_uri(raw)
        identity = _guangya_identity(uri) or _guangya_identity(raw)
        if identity:
            return "guangya", uri, identity
    if "pan.xunlei.com" in lower:
        identity = raw.split("?")[0].rstrip("/").split("/")[-1]
        uri = raw.split("#", 1)[0]
        return "xunlei", uri, identity
    return "", "", ""


def _collect_raw_urls(context_html: str, context_text: str) -> List[Tuple[str, str]]:
    """Return list of (url, extractor)."""
    raw_html = str(context_html or "")
    raw_text = str(context_text or "")
    decoded_html = _decode_blob(raw_html)
    decoded_text = _decode_blob(raw_text)
    found: List[Tuple[str, str]] = []

    def add(url: str, extractor: str) -> None:
        url = str(url or "").strip()
        if url:
            found.append((url, extractor))

    blob = decoded_text + "\n" + decoded_html
    for matched in _GUANGYA_RE.finditer(blob):
        add(matched.group(0), "visible_text")
    for matched in _XUNLEI_RE.finditer(blob):
        add(matched.group(0), "visible_text")
    for matched in _MAGNET_RE.finditer(blob):
        add(matched.group(0), "visible_text")
    for matched in _ED2K_RE.finditer(blob):
        add(matched.group(0), "visible_text")
    for matched in _OTHER_HOST_RE.finditer(blob):
        add(matched.group(0), "visible_text")

    for matched in _ATTR_URL_RE.finditer(raw_html):
        attr = matched.group(0).split("=", 1)[0].strip().lower()
        value = _decode_blob(matched.group(2))
        extractor = "href"
        if "clipboard" in attr or "copy" in attr:
            extractor = "clipboard"
        elif attr.startswith("data-"):
            extractor = "data"
        elif attr == "onclick":
            extractor = "onclick"
        elif attr == "value":
            extractor = "data"
        add(value, extractor)
        for nested in (
            _GUANGYA_RE.findall(value)
            + _XUNLEI_RE.findall(value)
            + _MAGNET_RE.findall(value)
            + _ED2K_RE.findall(value)
            + _OTHER_HOST_RE.findall(value)
        ):
            add(nested, extractor)

    for matched in _JS_URL_RE.finditer(raw_html):
        value = matched.group(2) or matched.group(4) or ""
        add(_decode_blob(value), "javascript")

    for matched in _JSON_URL_RE.finditer(raw_html):
        add(_decode_blob(matched.group(1)), "json")

    return found


def extract_message_resource_candidates_v209(
    context_html: str,
    context_text: str = "",
) -> List[Dict[str, Any]]:
    """统一消息级资源提取器：直接吃原始 message HTML。"""
    by_key: Dict[str, Dict[str, Any]] = {}
    other_urls: List[Dict[str, str]] = []
    other_seen: set = set()
    rank = {
        "clipboard": 5,
        "onclick": 4,
        "javascript": 4,
        "json": 4,
        "data": 3,
        "href": 2,
        "wrapped_redirect": 2,
        "visible_text": 1,
    }
    for url, extractor in _collect_raw_urls(context_html, context_text):
        unwrapped = _unwrap_redirect(url)
        kind, uri, identity = _classify_protocol(unwrapped)
        if kind and identity:
            key = f"{kind}:{identity}"
            final_extractor = (
                "wrapped_redirect"
                if unwrapped != url and extractor in {"href", "data", "visible_text"}
                else extractor
            )
            row = {
                "type": kind,
                "uri": uri,
                "identity": identity,
                "passcode": "",
                "extractor": final_extractor,
            }
            if kind == "xunlei":
                pwd = _PWD_IN_URL_RE.search(uri) or _PWD_IN_URL_RE.search(unwrapped)
                if pwd:
                    row["passcode"] = pwd.group(1)
            previous = by_key.get(key)
            if previous is None or rank.get(final_extractor, 0) > rank.get(str(previous.get("extractor") or ""), 0):
                by_key[key] = row
            continue
        other = _classify_other_url(unwrapped)
        if other:
            okey = f"{other.get('kind')}:{other.get('uri')}"
            if okey not in other_seen:
                other_seen.add(okey)
                other_urls.append(other)
    rows = list(by_key.values())
    for row in rows:
        row.setdefault("_other_urls", other_urls)
    if not rows and other_urls:
        return [{
            "type": "",
            "uri": "",
            "identity": "",
            "passcode": "",
            "extractor": "",
            "_other_urls": other_urls,
            "_diagnostic_only": True,
        }]
    return rows


def extract_message_resources_bundle_v209(
    context_html: str,
    context_text: str = "",
) -> Dict[str, Any]:
    """Return actionable candidates + other_urls for one message."""
    extracted = extract_message_resource_candidates_v209(context_html, context_text)
    other_urls: List[Dict[str, str]] = []
    candidates: List[Dict[str, Any]] = []
    for item in extracted:
        if item.get("_other_urls") and not other_urls:
            other_urls = list(item.get("_other_urls") or [])
        if item.get("_diagnostic_only") or not item.get("type"):
            continue
        clean = {k: v for k, v in item.items() if not str(k).startswith("_")}
        candidates.append(clean)
    return {"candidates": candidates, "other_urls": other_urls}


def _message_passcode(context_text: str, kind: str) -> str:
    text = str(context_text or "")
    if kind == "xunlei":
        matched = re.search(r"(?i)(?:pwd|passcode|password|密码|提取码)[:：\s]*([A-Za-z0-9]{4,8})", text)
        return str(matched.group(1) if matched else "")
    if kind == "guangya":
        matched = re.search(r"(?i)(?:code|pwd|密码|提取码)[:：\s]*([A-Za-z0-9]{3,12})", text)
        return str(matched.group(1) if matched else "")
    return ""


def enrich_candidates_with_local_passcode(candidates: List[Dict[str, Any]], context_text: str) -> List[Dict[str, Any]]:
    """验证码严格 message-local。"""
    output = []
    for row in candidates or []:
        item = dict(row)
        kind = str(item.get("type") or "")
        if kind in {"xunlei", "guangya"} and not item.get("passcode"):
            item["passcode"] = _message_passcode(context_text, kind)
        output.append(item)
    return output


def _strip_title_noise(value: str) -> str:
    text = str(value or "").strip()
    text = re.sub(r"〖[^〗]*〗", " ", text)
    text = re.sub(r"【[^】]*】", " ", text)
    text = _QUALITY_NOISE.sub(" ", text)
    text = re.sub(r"(?i)\bS\d{1,2}\s*E\d{1,4}\b", " ", text)
    text = re.sub(r"第\s*\d{1,3}\s*季", " ", text)
    text = re.sub(r"更至\s*EP?\d{1,4}", " ", text, flags=re.I)
    text = re.sub(r"[（(]\s*(?:19|20)\d{2}\s*[）)]", " ", text)
    text = re.sub(r"\s+", " ", text).strip(" -/|")
    return text[:200]


def _title_candidates_from_raw(raw_title: str) -> List[str]:
    cleaned = _strip_title_noise(raw_title)
    if not cleaned:
        return []
    parts = re.split(r"[/／|｜]", cleaned)
    out = []
    seen = set()
    for part in parts:
        token = part.strip()
        if not token or token in seen:
            continue
        seen.add(token)
        out.append(token)
    # Only keep the joined form when it is NOT an alias-separator compound.
    if cleaned not in seen and not re.search(r"[/／|｜]", cleaned):
        out.insert(0, cleaned)
    return out[:8]


def parse_message_title_metadata_v209(visible_text: str) -> Dict[str, Any]:
    """Parse channel title templates into structured metadata (message-local)."""
    text = str(visible_text or "")
    raw_title = ""
    type_hint = ""
    labelled = _LABELLED_TITLE_RE.search(text)
    series = _SERIES_EMOJI_RE.search(text)
    movie = _MOVIE_EMOJI_RE.search(text)
    if labelled:
        raw_title = labelled.group(1).strip()
    elif series:
        raw_title = series.group(1).strip()
        type_hint = "tv"
    elif movie:
        raw_title = movie.group(1).strip()
        type_hint = "movie"
    else:
        for line in text.splitlines()[:8]:
            line = line.strip()
            if not line or re.match(
                r"^(?:类型|TMDB|画质|质量|集数|大小|分享|简介|迅雷|磁力|密码|提取码|115)\s*[：:]",
                line,
                re.I,
            ):
                continue
            if re.search(r"[（(](?:19|20)\d{2}[）)]|\b(?:19|20)\d{2}\b", line):
                raw_title = line
                break
    year = ""
    year_match = _YEAR_RE.search(raw_title) or _YEAR_RE.search(text[:400])
    if year_match:
        year = year_match.group(1) or year_match.group(2) or ""
    season_hint = None
    season_match = _SEASON_RE.search(raw_title) or _SEASON_RE.search(text[:500])
    if season_match:
        season_hint = int(season_match.group(1) or season_match.group(2) or 0) or None
    episode_hint = ""
    ep_match = _EPISODE_RE.search(raw_title) or _EPISODE_RE.search(text[:500])
    if ep_match:
        if re.search(r"(?i)S\d+", ep_match.group(0) or ""):
            episode_hint = ep_match.group(0)
        else:
            num = next((g for g in ep_match.groups() if g), "")
            if num:
                episode_hint = f"E{int(num)}"
    total_episode_hint = None
    total_match = _TOTAL_EP_RE.search(raw_title) or _TOTAL_EP_RE.search(text[:400])
    if total_match:
        total_episode_hint = int(next(g for g in total_match.groups() if g))
    tmdb_id = ""
    tmdb_match = _TMDB_RE.search(text)
    if tmdb_match:
        tmdb_id = tmdb_match.group(1)
    match_title = _strip_title_noise(raw_title)
    title_candidates = _title_candidates_from_raw(raw_title or match_title)
    if match_title and ("/" in match_title or "／" in match_title):
        match_title = title_candidates[0] if title_candidates else re.split(r"[/／]", match_title)[0].strip()
    return {
        "raw_title": (raw_title or match_title)[:300],
        "match_title": match_title[:200],
        "title_candidates": title_candidates,
        "media_type_hint": type_hint,
        "tmdb_id": tmdb_id,
        "year": year,
        "season_hint": season_hint,
        "episode_hint": episode_hint,
        "total_episode_hint": total_episode_hint,
    }


def build_inbox_row_from_message_block(
    block: Dict[str, Any],
    *,
    now: Optional[float] = None,
) -> Dict[str, Any]:
    """Build one ResourceGroup inbox row from a raw message block."""
    now = float(now if now is not None else time.time())
    raw_html = str(block.get("raw_html") or "")
    visible_text = str(block.get("visible_text") or "")
    bundle = extract_message_resources_bundle_v209(raw_html, visible_text)
    candidates = enrich_candidates_with_local_passcode(bundle.get("candidates") or [], visible_text)
    other_urls = list(bundle.get("other_urls") or [])
    meta = parse_message_title_metadata_v209(visible_text)
    channel = str(block.get("channel") or block.get("source_url") or "")
    source_url = str(block.get("source_url") or channel)
    message_id = str(block.get("message_id") or "")
    group_id = f"{channel}:{message_id}" if message_id else hashlib.sha1(
        f"{channel}|{meta.get('raw_title')}|{len(candidates)}".encode("utf-8", "ignore")
    ).hexdigest()[:20]
    raw_hash = hashlib.sha1(
        f"{channel}|{message_id}|{meta.get('raw_title')}|{len(candidates)}|{len(other_urls)}".encode("utf-8", "ignore")
    ).hexdigest()[:20]
    provenance = [{
        "channel": channel,
        "message_id": message_id,
        "extractor": ",".join(sorted({str(c.get("extractor") or "") for c in candidates if c.get("extractor")})) or "raw",
    }]
    trace_id = stable_trace_id(channel, message_id, group_id, raw_hash)
    return {
        "inbox_id": group_id,
        "channel": channel,
        "source_url": source_url,
        "message_id": message_id,
        "resource_group_id": group_id,
        "resource_trace_id": trace_id,
        "raw_title": meta.get("raw_title") or "",
        "match_title": meta.get("match_title") or "",
        "title_candidates": list(meta.get("title_candidates") or []),
        "media_type_hint": meta.get("media_type_hint") or "",
        "tmdb_id": meta.get("tmdb_id") or "",
        "year": meta.get("year") or "",
        "season_hint": meta.get("season_hint"),
        "episode_hint": meta.get("episode_hint") or "",
        "total_episode_hint": meta.get("total_episode_hint"),
        "candidates": candidates,
        "other_urls": other_urls,
        "provenance": provenance,
        "discovered_at": now,
        "last_seen_at": now,
        "expires_at": now + _INBOX_RETENTION_SECONDS,
        "raw_hash": raw_hash,
        "origin": "inbox",
    }


def build_inbox_row_from_entry(entry: Dict[str, Any], *, now: Optional[float] = None) -> Dict[str, Any]:
    now = float(now if now is not None else time.time())
    channel = str(entry.get("source_url") or entry.get("channel") or "")
    message_id = str(entry.get("message_id") or "")
    group_id = str(entry.get("resource_group_id") or "")
    title = str(entry.get("display_title") or entry.get("title") or entry.get("match_title") or "")[:300]
    candidates: List[Dict[str, Any]] = []
    share = str(entry.get("share_url") or "").strip()
    if share:
        kind, uri, identity = _classify_protocol(share)
        if kind:
            candidates.append({
                "type": kind,
                "uri": uri,
                "identity": identity,
                "passcode": str(entry.get("share_code") or entry.get("passcode") or ""),
                "extractor": str(entry.get("link_style") or "visible_text"),
            })
    for item in entry.get("xunlei_sources") or []:
        if not isinstance(item, dict):
            continue
        uri = str(item.get("url") or item.get("uri") or "")
        kind, uri, identity = _classify_protocol(uri)
        if kind:
            candidates.append({
                "type": kind,
                "uri": uri,
                "identity": identity,
                "passcode": str(item.get("passcode") or item.get("pwd") or ""),
                "extractor": str(item.get("extractor") or "href"),
            })
    for item in entry.get("external_sources") or []:
        if not isinstance(item, dict):
            continue
        candidates.append({
            "type": str(item.get("type") or ""),
            "uri": str(item.get("uri") or ""),
            "identity": str(item.get("identity") or ""),
            "passcode": str(item.get("passcode") or ""),
            "extractor": str(item.get("extractor") or "visible_text"),
        })
    context_html = str(entry.get("context_html") or entry.get("html") or "")
    context_text = str(entry.get("text") or "")
    other_urls: List[Dict[str, str]] = []
    if context_html or context_text:
        bundle = extract_message_resources_bundle_v209(context_html, context_text)
        extracted = enrich_candidates_with_local_passcode(bundle.get("candidates") or [], context_text)
        other_urls = list(bundle.get("other_urls") or [])
        seen = {f"{c.get('type')}:{c.get('identity')}" for c in candidates}
        for item in extracted:
            key = f"{item.get('type')}:{item.get('identity')}"
            if key not in seen:
                seen.add(key)
                candidates.append(item)
    meta = parse_message_title_metadata_v209(context_text or title)
    raw_hash = hashlib.sha1(
        f"{channel}|{message_id}|{group_id}|{title}|{len(candidates)}".encode("utf-8", "ignore")
    ).hexdigest()[:20]
    inbox_id = group_id or f"{channel}:{message_id}:{raw_hash}"
    return {
        "inbox_id": inbox_id,
        "channel": channel,
        "source_url": channel,
        "message_id": message_id,
        "resource_group_id": group_id or inbox_id,
        "raw_title": meta.get("raw_title") or title,
        "match_title": meta.get("match_title") or title,
        "title_candidates": list(meta.get("title_candidates") or ([title] if title else [])),
        "media_type_hint": meta.get("media_type_hint") or "",
        "tmdb_id": str(entry.get("tmdb_id") or meta.get("tmdb_id") or ""),
        "year": str(entry.get("year") or entry.get("year_hint") or meta.get("year") or ""),
        "season_hint": entry.get("season_hint") or entry.get("season") or meta.get("season_hint"),
        "episode_hint": entry.get("episode_hint") or meta.get("episode_hint") or "",
        "total_episode_hint": entry.get("total_episode_hint") or meta.get("total_episode_hint"),
        "candidates": [c for c in candidates if c.get("type")],
        "other_urls": other_urls,
        "provenance": [{"channel": channel, "message_id": message_id, "extractor": "legacy_entry"}],
        "discovered_at": now,
        "last_seen_at": now,
        "expires_at": now + _INBOX_RETENTION_SECONDS,
        "raw_hash": raw_hash,
        "origin": "legacy",
    }


def upsert_inbox_rows(store: Dict[str, Any], rows: Iterable[Dict[str, Any]], *, now: Optional[float] = None) -> Dict[str, Any]:
    now = float(now if now is not None else time.time())
    items = dict(store.get("items") or {}) if isinstance(store, dict) else {}
    stats = {"new": 0, "updated": 0}
    new_rows: List[Dict[str, Any]] = []
    updated_rows: List[Dict[str, Any]] = []
    identity_index: Dict[str, str] = {}
    for existing_id, existing in items.items():
        for cand in (existing or {}).get("candidates") or []:
            if not isinstance(cand, dict):
                continue
            if cand.get("type") and cand.get("identity"):
                identity_index[f"{cand.get('type')}:{cand.get('identity')}"] = existing_id

    for row in rows or []:
        if not isinstance(row, dict):
            continue
        if not row.get("candidates") and not row.get("other_urls"):
            continue
        inbox_id = str(row.get("inbox_id") or "")
        if not inbox_id:
            continue
        merge_into = inbox_id
        for cand in row.get("candidates") or []:
            if not isinstance(cand, dict):
                continue
            ikey = f"{cand.get('type')}:{cand.get('identity')}"
            prev_id = identity_index.get(ikey)
            if prev_id and prev_id in items:
                merge_into = prev_id
                break
        previous = dict(items.get(merge_into) or {})
        is_new = not previous
        merged = dict(previous)
        merged.update({
            k: v for k, v in row.items()
            if k not in {"discovered_at", "candidates", "provenance", "other_urls"}
        })
        if previous.get("discovered_at"):
            merged["discovered_at"] = previous.get("discovered_at")
        else:
            merged["discovered_at"] = row.get("discovered_at") or now
        merged["last_seen_at"] = now
        merged["expires_at"] = now + _INBOX_RETENTION_SECONDS
        merged["inbox_id"] = merge_into
        seen: Dict[str, Dict[str, Any]] = {}
        candidates: List[Dict[str, Any]] = []
        for item in list(previous.get("candidates") or []) + list(row.get("candidates") or []):
            if not isinstance(item, dict) or not item.get("type"):
                continue
            key = f"{item.get('type')}:{item.get('identity')}"
            existing = seen.get(key)
            if existing is None:
                seen[key] = dict(item)
                candidates.append(seen[key])
            else:
                if item.get("passcode") and not existing.get("passcode"):
                    existing["passcode"] = item.get("passcode")
                if item.get("uri") and not existing.get("uri"):
                    existing["uri"] = item.get("uri")
        merged["candidates"] = candidates
        other = list(previous.get("other_urls") or [])
        oseen = {f"{o.get('kind')}:{o.get('uri')}" for o in other if isinstance(o, dict)}
        for item in row.get("other_urls") or []:
            if not isinstance(item, dict):
                continue
            key = f"{item.get('kind')}:{item.get('uri')}"
            if key not in oseen:
                oseen.add(key)
                other.append(item)
        merged["other_urls"] = other
        prov = list(previous.get("provenance") or [])
        pseen = {f"{p.get('channel')}|{p.get('message_id')}" for p in prov if isinstance(p, dict)}
        for item in row.get("provenance") or []:
            if not isinstance(item, dict):
                continue
            key = f"{item.get('channel')}|{item.get('message_id')}"
            if key not in pseen:
                pseen.add(key)
                prov.append(item)
        merged["provenance"] = prov
        if previous.get("origin") and row.get("origin") and previous.get("origin") != row.get("origin"):
            merged["origin"] = "both"
        elif not merged.get("origin"):
            merged["origin"] = row.get("origin") or "inbox"
        # Keep stable resource_trace_id across refreshes.
        if previous.get("resource_trace_id"):
            merged["resource_trace_id"] = previous.get("resource_trace_id")
        elif not merged.get("resource_trace_id"):
            merged["resource_trace_id"] = stable_trace_id(
                merged.get("channel"), merged.get("message_id"), merge_into, merged.get("raw_hash"),
            )
        items[merge_into] = merged
        for cand in candidates:
            identity_index[f"{cand.get('type')}:{cand.get('identity')}"] = merge_into
        if is_new:
            stats["new"] += 1
            new_rows.append(merged)
        else:
            stats["updated"] += 1
            updated_rows.append(merged)

    alive = {
        key: value
        for key, value in items.items()
        if float((value or {}).get("expires_at") or 0) >= now
    }
    if len(alive) > _INBOX_MAX_ROWS:
        ordered = sorted(alive.items(), key=lambda kv: float((kv[1] or {}).get("last_seen_at") or 0))
        alive = dict(ordered[-_INBOX_MAX_ROWS:])
    return {
        "updated_at": now,
        "count": len(alive),
        "items": alive,
        "stats": stats,
        "new_rows": new_rows,
        "updated_rows": updated_rows,
    }


def convert_inbox_row_to_entry(row: Dict[str, Any]) -> Dict[str, Any]:
    """Convert inbox ResourceGroup into legacy-compatible channel entry schema."""
    candidates = [c for c in (row.get("candidates") or []) if isinstance(c, dict) and c.get("type")]
    guangya = next((c for c in candidates if c.get("type") == "guangya"), None)
    xunlei_sources = [
        {
            "url": c.get("uri"),
            "uri": c.get("uri"),
            "passcode": c.get("passcode"),
            "extractor": c.get("extractor"),
            "identity": c.get("identity"),
        }
        for c in candidates if c.get("type") == "xunlei"
    ]
    external_sources = [
        {
            "type": c.get("type"),
            "uri": c.get("uri"),
            "identity": c.get("identity"),
            "passcode": c.get("passcode"),
            "extractor": c.get("extractor"),
        }
        for c in candidates if c.get("type") in {"magnet", "ed2k"}
    ]
    title = str(row.get("match_title") or row.get("raw_title") or "")
    episode_hint = str(row.get("episode_hint") or "")
    text_parts = [str(row.get("raw_title") or title)]
    if episode_hint:
        text_parts.append(episode_hint)
    if row.get("year"):
        text_parts.append(str(row.get("year")))
    return {
        "share_url": str((guangya or {}).get("uri") or ""),
        "share_id": str((guangya or {}).get("identity") or ""),
        "text": "\n".join(p for p in text_parts if p)[:2200],
        "source_url": str(row.get("source_url") or row.get("channel") or ""),
        "source_label": str(row.get("channel") or ""),
        "priority": 0 if "regeng" in str(row.get("channel") or "").lower() else 1,
        "link_style": str((guangya or {}).get("extractor") or "inbox"),
        "stale": False,
        # False so ChannelCursorEvent can treat fresh Inbox-only rows as live events.
        "cached_index": False,
        "message_id": str(row.get("message_id") or ""),
        "display_title": title,
        "match_title": title,
        "title_candidates": list(row.get("title_candidates") or []),
        "tmdb_id": str(row.get("tmdb_id") or ""),
        "year": row.get("year") or "",
        "year_hint": int(row["year"]) if str(row.get("year") or "").isdigit() else None,
        "season_hint": row.get("season_hint"),
        "episode_hint": episode_hint,
        "total_episode_hint": row.get("total_episode_hint"),
        "resource_group_id": str(row.get("resource_group_id") or row.get("inbox_id") or ""),
        "resource_trace_id": str(row.get("resource_trace_id") or ""),
        "xunlei_sources": xunlei_sources,
        "external_sources": external_sources,
        "other_urls": list(row.get("other_urls") or []),
        "candidate_types": [str(c.get("type")) for c in candidates],
        "provenance": list(row.get("provenance") or []),
        "origin": str(row.get("origin") or "inbox"),
        "inbox_id": str(row.get("inbox_id") or ""),
    }


def union_legacy_and_inbox_entries(
    legacy_entries: Iterable[Dict[str, Any]],
    inbox_store: Dict[str, Any],
) -> List[Dict[str, Any]]:
    """Union legacy channel_index entries with inbox-converted entries; dedup by protocol identity."""
    by_identity: Dict[str, Dict[str, Any]] = {}
    order: List[str] = []

    def _identities(entry: Dict[str, Any]) -> List[str]:
        keys = []
        share = str(entry.get("share_url") or "")
        if share:
            kind, _uri, identity = _classify_protocol(share)
            if kind and identity:
                keys.append(f"{kind}:{identity}")
        for item in entry.get("xunlei_sources") or []:
            if isinstance(item, dict):
                kind, _uri, identity = _classify_protocol(str(item.get("url") or item.get("uri") or ""))
                if kind and identity:
                    keys.append(f"{kind}:{identity}")
        for item in entry.get("external_sources") or []:
            if isinstance(item, dict) and item.get("type") and item.get("identity"):
                keys.append(f"{item.get('type')}:{item.get('identity')}")
        return keys

    def _merge(entry: Dict[str, Any], origin: str) -> None:
        keys = _identities(entry)
        if not keys:
            fallback = str(entry.get("resource_group_id") or entry.get("inbox_id") or "")
            if not fallback:
                return
            keys = [f"group:{fallback}"]
        primary = keys[0]
        existing_key = None
        for key in keys:
            if key in by_identity:
                existing_key = key
                break
        if existing_key is None:
            row = dict(entry)
            row["origin"] = origin
            by_identity[primary] = row
            for key in keys:
                by_identity[key] = row
            order.append(primary)
            return
        current = by_identity[existing_key]
        if origin == "inbox" and current.get("origin") == "legacy":
            current["origin"] = "both"
        elif origin == "legacy" and current.get("origin") == "inbox":
            current["origin"] = "both"
        if entry.get("share_url") and not current.get("share_url"):
            current["share_url"] = entry.get("share_url")
            current["share_id"] = entry.get("share_id")
        if entry.get("xunlei_sources"):
            existing = list(current.get("xunlei_sources") or [])
            seen = {str(x.get("url") or x.get("uri") or "") for x in existing}
            for item in entry.get("xunlei_sources") or []:
                uri = str((item or {}).get("url") or (item or {}).get("uri") or "")
                if uri and uri not in seen:
                    existing.append(item)
                    seen.add(uri)
            current["xunlei_sources"] = existing
        if entry.get("external_sources"):
            existing = list(current.get("external_sources") or [])
            seen = {f"{x.get('type')}:{x.get('identity')}" for x in existing}
            for item in entry.get("external_sources") or []:
                key = f"{(item or {}).get('type')}:{(item or {}).get('identity')}"
                if key not in seen:
                    existing.append(item)
                    seen.add(key)
            current["external_sources"] = existing
        prov = list(current.get("provenance") or [])
        pseen = {f"{p.get('channel')}|{p.get('message_id')}" for p in prov if isinstance(p, dict)}
        for item in entry.get("provenance") or []:
            if not isinstance(item, dict):
                continue
            key = f"{item.get('channel')}|{item.get('message_id')}"
            if key not in pseen:
                pseen.add(key)
                prov.append(item)
        current["provenance"] = prov
        for key in keys:
            by_identity[key] = current

    for entry in legacy_entries or []:
        if isinstance(entry, dict):
            tagged = dict(entry)
            tagged.setdefault("origin", "legacy")
            _merge(tagged, "legacy")
    items = (inbox_store or {}).get("items") or {}
    for row in items.values():
        if not isinstance(row, dict) or not row.get("candidates"):
            continue
        _merge(convert_inbox_row_to_entry(row), "inbox")

    result = []
    seen_obj = set()
    for key in order:
        row = by_identity.get(key)
        if row is None:
            continue
        obj_id = id(row)
        if obj_id in seen_obj:
            continue
        seen_obj.add(obj_id)
        result.append(row)
    return result


def shadow_match_inbox_for_subscribe(store: Dict[str, Any], subscribe: Any, matcher) -> List[Dict[str, Any]]:
    """Return inbox rows matcher(subscribe, synthetic_entry) accepts."""
    hits = []
    items = (store or {}).get("items") or {}
    for row in items.values():
        if not isinstance(row, dict) or not row.get("candidates"):
            continue
        synthetic = convert_inbox_row_to_entry(row)
        try:
            matched, reason = matcher(synthetic, subscribe)
        except Exception:
            matched, reason = False, "matcher_error"
        if matched:
            hits.append({"inbox_id": row.get("inbox_id"), "reason": reason, "row": row, "entry": synthetic})
    return hits


def summarize_page_extract_stats_v209(blocks: List[Dict[str, Any]], rows: List[Dict[str, Any]]) -> Dict[str, Any]:
    guangya = xunlei = magnet = ed2k = other = hidden = visible = 0
    for row in rows or []:
        for cand in row.get("candidates") or []:
            kind = str(cand.get("type") or "")
            if kind == "guangya":
                guangya += 1
            elif kind == "xunlei":
                xunlei += 1
            elif kind == "magnet":
                magnet += 1
            elif kind == "ed2k":
                ed2k += 1
            extractor = str(cand.get("extractor") or "")
            if extractor in {"clipboard", "data", "onclick", "javascript", "json", "wrapped_redirect"}:
                hidden += 1
            elif extractor in {"href", "visible_text"}:
                visible += 1
        other += len(row.get("other_urls") or [])
    return {
        "messages": len(blocks or []),
        "resource_groups": len(rows or []),
        "guangya": guangya,
        "xunlei": xunlei,
        "magnet": magnet,
        "ed2k": ed2k,
        "other": other,
        "hidden": hidden,
        "visible": visible,
    }


