    def _dispatch_subscribe_search(self, *args, progress_callback=None, **kwargs):
        """宿主 scheduler takeover 的最终固定分流。

        - 显式 progress_callback：供 Scheduler inspect.signature 检测；
        - 位置参数只归一化一次，之后一律 **kwargs 转发，禁止 *args + 同名 kwargs；
