            self._xunlei_runtime_reservations.pop(sid, None)

    def _note_xunlei_flash_diag_v209(self, subscribe: Any, flash: Dict[str, Any]) -> None:
        """Attach structured Xunlei diagnostics without changing flash protocol."""
        if not isinstance(flash, dict):
            return
        try:
            from .transfer_diag_v209 import make_candidate_trace_id, make_diag
        except Exception:
            return
        sid = int(getattr(subscribe, "id", 0) or 0)
        share_id = str(flash.get("share_id") or flash.get("identity") or "").strip()
        resource_trace = str(flash.get("resource_trace_id") or "").strip()
        cand_trace = str(flash.get("candidate_trace_id") or "").strip() or (
            make_candidate_trace_id("xunlei", share_id) if share_id else ""
        )
        diags = list(flash.get("candidate_diags") or [])
        message = str(flash.get("message") or "")
        low = message.lower()
        if flash.get("success") and (flash.get("handled") or int(flash.get("successful_files") or 0) > 0):
            code = "XUNLEI_TRANSFER_CONFIRMED"
            if any(token in message for token in ("已存在", "已经存在", "already")):
                code = "XUNLEI_ALREADY_PRESENT"
            row = make_diag(
                state="SUCCESS",
                reason_code=code,
                stage="REMOTE_VERIFY",
                source="xunlei",
                message=message[:360],
                resource_trace_id=resource_trace,
                candidate_trace_id=cand_trace,
                sid=sid,
                evidence={"share_id": share_id, "successful_files": flash.get("successful_files")},
            )
        elif any(token in message or token in low for token in ("失效", "过期", "不存在", "expired", "deleted", "404")):
            row = make_diag(
                state="FAILED_RETRYABLE",
                reason_code="SHARE_EXPIRED",
                stage="SHARE_INSPECT",
                source="xunlei",
                message=message[:360],
                resource_trace_id=resource_trace,
                candidate_trace_id=cand_trace,
                sid=sid,
                evidence={"share_id": share_id},
            )
        elif any(token in message or token in low for token in ("认证", "登录", "401", "unauthorized", "token")):
            row = make_diag(
                state="FAILED_FINAL",
                reason_code="AUTH_ERROR",
                stage="SHARE_INSPECT",
                source="xunlei",
                message=message[:360],
                resource_trace_id=resource_trace,
                candidate_trace_id=cand_trace,
                sid=sid,
            )
        elif any(token in low for token in ("timeout", "超时")):
            row = make_diag(
                state="FAILED_RETRYABLE",
                reason_code="HTTP_TIMEOUT",
                stage="SHARE_INSPECT",
                source="xunlei",
                message=message[:360],
                resource_trace_id=resource_trace,
                candidate_trace_id=cand_trace,
                sid=sid,
            )
        elif any(token in low for token in ("network", "connection", "连接")):
            row = make_diag(
                state="FAILED_RETRYABLE",
                reason_code="NETWORK_ERROR",
                stage="SHARE_INSPECT",
                source="xunlei",
                message=message[:360],
                resource_trace_id=resource_trace,
                candidate_trace_id=cand_trace,
                sid=sid,
            )
        elif "json" in low or "模板" in message:
            row = make_diag(
                state="FAILED_RETRYABLE",
                reason_code="XUNLEI_TEMPLATE_BUILD_FAILED",
                stage="SUBMIT",
                source="xunlei",
                message=message[:360],
                resource_trace_id=resource_trace,
                candidate_trace_id=cand_trace,
                sid=sid,
            )
        elif flash.get("handled"):
            # e.g. no missing episodes — treat as complete skip
            row = make_diag(
                state="SKIPPED_COMPLETE",
                reason_code="CURRENT_TARGET_ALREADY_SATISFIED",
                stage="LIBRARY_PREFLIGHT",
                source="xunlei",
                message=message[:360],
                resource_trace_id=resource_trace,
                candidate_trace_id=cand_trace,
                sid=sid,
                subscription_level=True,
            )
        else:
            return
        diags.append(row)
        flash["candidate_diags"] = diags
        if cand_trace:
            flash["candidate_trace_id"] = cand_trace
        note = getattr(self, "_note_candidate_diag_v209", None)
        if callable(note):
            try:
                note(row)
            except Exception:
                pass
        # Prefer first channel candidate's resource_trace_id when missing.
        if not resource_trace:
            try:
                rows = self._channel_xunlei_candidates_v11214(subscribe) if hasattr(self, "_channel_xunlei_candidates_v11214") else []
                for cand in rows or []:
                    rid = str((cand or {}).get("resource_trace_id") or "").strip()
                    if rid:
                        flash["resource_trace_id"] = rid
                        row["resource_trace_id"] = rid
                        break
            except Exception:
                pass

    def api_xunlei_flash_test(self, share_url: str = "", passcode: str = "") -> Dict[str, Any]:
        parsed = parse_xunlei_share(str(share_url or ""), label="test")
        if not parsed:
            return {"success": False, "message": "请输入有效的 https://pan.xunlei.com/s/... 分享链接"}
        row = parsed[0]
        if passcode:
            row["passcode"] = str(passcode).strip()
        try:
            info = self._xunlei_share_info(str(row.get("share_id") or ""), str(row.get("passcode") or ""))
            files = self._xunlei_share_files(str(row.get("share_id") or ""), str(info.get("pass_code_token") or ""))
            return {"success": True, "message": f"迅雷分享可读，共发现 {len(files)} 个文件", "data": {"share_id": str(row.get("share_id") or ""), "title": str(info.get("title") or ""), "files": len(files), "with_captcha": bool(self._xunlei_runtime_captcha_token or self._xunlei_captcha_token or self._xunlei_captcha_init_json)}}
        except Exception as err:
            return {"success": False, "message": str(err)[:500]}

    def api_xunlei_flash_state(self) -> Dict[str, Any]:
        state = self._xunlei_state()
        rows = []
        for item in (state.get("items") or {}).values():
            if not isinstance(item, dict):
                continue
            rows.append({"state": str(item.get("state") or ""), "subscribe_id": int(item.get("subscribe_id") or 0), "share_id": str(item.get("share_id") or "")[:20], "path": str(item.get("path") or "")[:300], "episodes": list(item.get("episodes") or []), "message": str(item.get("message") or "")[:300], "updated_at": str(item.get("updated_at") or "")})
        rows.sort(key=lambda item: str(item.get("updated_at") or ""), reverse=True)
        return {"success": True, "count": len(rows), "data": rows[:100]}

    def get_api(self) -> List[Dict[str, Any]]:
        apis = list(super().get_api() or [])
        paths = {str(item.get("path") or "") for item in apis if isinstance(item, dict)}
        if "/xunlei/flash/test" not in paths:
            apis.append({"path": "/xunlei/flash/test", "endpoint": self.api_xunlei_flash_test, "methods": ["POST"], "summary": "测试迅雷分享读取"})
        if "/xunlei/flash/state" not in paths:
            apis.append({"path": "/xunlei/flash/state", "endpoint": self.api_xunlei_flash_state, "methods": ["GET"], "summary": "查看迅雷秒传状态"})
        return apis


